class Solution:
    def checkTwoChessboards(self, start: List[int], target: List[int]) -> bool:
        from collections import deque
        moves = [(1,2),(2,1),(2,-1),(1,-2),(-1,-2),(-2,-1),(-2,1),(-1,2)]
        seen = set()
        q = deque([(start[0], start[1], 0)])
        seen.add((start[0], start[1]))
        while q:
            x, y, p = q.popleft()
            if [x, y] == target and p == 0:
                return True
            for dx, dy in moves:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 8 and 0 <= ny < 8 and (nx, ny) not in seen:
                    seen.add((nx, ny))
                    q.append((nx, ny, 1 - p))
        return False

