class Solution {
public:
    bool checkTwoChessboards(vector<int>& start, vector<int>& target) {
        int mv[8][2] = {{1,2},{2,1},{2,-1},{1,-2},{-1,-2},{-2,-1},{-2,1},{-1,2}};
        bool seen[8][8] = {};
        queue<array<int,3>> q;
        q.push({start[0], start[1], 0});
        seen[start[0]][start[1]] = true;
        while (!q.empty()) {
            auto [x, y, p] = q.front(); q.pop();
            if (x == target[0] && y == target[1] && p == 0) return true;
            for (auto& m : mv) {
                int nx = x + m[0], ny = y + m[1];
                if (nx >= 0 && nx < 8 && ny >= 0 && ny < 8 && !seen[nx][ny]) {
                    seen[nx][ny] = true;
                    q.push({nx, ny, 1 - p});
                }
            }
        }
        return false;
    }
};

