class Solution {
    public boolean checkTwoChessboards(int[] start, int[] target) {
        int[][] mv = {{1,2},{2,1},{2,-1},{1,-2},{-1,-2},{-2,-1},{-2,1},{-1,2}};
        boolean[][] seen = new boolean[8][8];
        Deque<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{start[0], start[1], 0});
        seen[start[0]][start[1]] = true;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            if (cur[0] == target[0] && cur[1] == target[1] && cur[2] == 0) return true;
            for (int[] m : mv) {
                int nx = cur[0] + m[0], ny = cur[1] + m[1];
                if (nx >= 0 && nx < 8 && ny >= 0 && ny < 8 && !seen[nx][ny]) {
                    seen[nx][ny] = true;
                    q.offer(new int[]{nx, ny, 1 - cur[2]});
                }
            }
        }
        return false;
    }
}

