var checkTwoChessboards = function(start, target) {
    const mv = [[1,2],[2,1],[2,-1],[1,-2],[-1,-2],[-2,-1],[-2,1],[-1,2]];
    const seen = Array.from({length: 8}, () => Array(8).fill(false));
    let q = [[start[0], start[1], 0]];
    seen[start[0]][start[1]] = true;
    while (q.length) {
        const [x, y, p] = q.shift();
        if (x === target[0] && y === target[1] && p === 0) return true;
        for (const [dx, dy] of mv) {
            const nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < 8 && ny >= 0 && ny < 8 && !seen[nx][ny]) {
                seen[nx][ny] = true;
                q.push([nx, ny, 1 - p]);
            }
        }
    }
    return false;
};
